+                    + "INFO"
+                    + "\",    \"log.logger\": \""
+                    + "some.package.for.logging.requests"
+                    + "\",    \"client.ip\": \""
+                    + randomIp()
+                    + "\",    \"http.request.method\": \""
+                    + randomFrom("GET", "POST")
+                    + "\",    \"http.request.id\": \""
+                    + random.nextInt()
+                    + "\",    \"http.request.bytes\": "
+                    + random.nextInt(1024)
+                    + ",    \"url.path\": \""
+                    + randomString(1024)
+                    + "\",    \"http.response.status_code\": "
